EXTRAS = [
dict(n=51, gr='wouldlike', vb='want,need,buy,ask,choose',
 c1="Want ou need?|'Want' é desejo e 'need' é necessidade. 'I want a new phone' (quero) é diferente de 'I need water' (preciso). Em pedidos educados, troque want por would like.",
 c2="Lojas de ferramentas|Nos EUA, 'hardware store' é a loja de ferramentas. Palavras úteis: 'screwdriver' (chave de fenda), 'hammer' (martelo), 'glue' (cola), 'nails' (pregos). Todo bricolador vive lá.",
 ar=("A gift for Lily","Gus needs a screwdriver to fix a lamp at home. He also wants a gift for his sister, Lily. In the shop, Abel helps him. \"What do you need?\" asks Abel. \"A small screwdriver and some glue,\" says Gus. \"And I'd like a toy for my sister.\" Abel shows him a blue toy robot. \"She'll love it!\" Gus pays and thanks Abel. At home he fixes the lamp first and then wraps the robot with colorful paper. Lily opens the gift and laughs: \"A robot! I love it!\"","Gus compra ferramentas e um robô de presente para a irmã.","O que Gus precisa?=A screwdriver|A map|A hat;;O que Lily ganha?=A toy robot|A book|A scarf"),
 ex="I'm in the mood for...=Estou com vontade de...~Desejo|I could use some help.=Eu aceitaria ajuda.~Pedir ajuda|I'm just looking.=Só estou olhando.~Loja|That's exactly what I need.=É exatamente o que preciso.~Achar algo|I'll think about it.=Vou pensar.~Decidir depois",
 tf="Want expressa desejo.=T|Need expressa necessidade.=T|Gus compra uma bicicleta.=F|Lily ganha um robô.=T",
 odd="screwdriver,hammer,glue,sandwich=sandwich|want,need,would like,table=table"),
dict(n=52, gr='wouldlike', vb='order,deliver,pay,wait,call',
 c1="Delivery e takeout|Nos EUA, 'delivery' é a entrega em casa e 'takeout' é pegar no balcão. No Reino Unido, 'takeaway' faz as duas coisas. Aplicativos como Uber Eats e DoorDash são muito usados.",
 c2="Pizza pelo mundo|A pizza nasceu em Nápoles, mas nos EUA ganhou versões como 'New York style' (fina e dobrada) e 'Chicago deep dish' (grossa, em forma de torta). 'Pepperoni' é o recheio mais popular.",
 ar=("Pizza night","Friday is pizza night on Maple Street. Pablo calls Maple Pizza and says, \"I'd like to order a large mushroom pizza with extra cheese, please.\" Suri takes the order and asks, \"What's your address?\" \"12 Maple Street.\" \"It will take thirty minutes. Cash or card?\" \"Card, please.\" At exactly seven thirty, the doorbell rings. The delivery boy is on the doorstep with a hot, fragrant pizza. Pablo pays and gives him a tip. \"Enjoy your meal!\" says the boy. Pablo smiles: the best part of Friday.","A pizza chega no horário combinado e Pablo dá gorjeta.","Que horas a pizza chega?=Seven thirty|Eight|Seven;;O que Pablo dá ao entregador?=A tip|A pizza|A coffee"),
 ex="I'd like to place an order.=Gostaria de fazer um pedido.~Ligação|Is delivery free?=A entrega é grátis?~Pergunta|Extra cheese, please.=Queijo extra, por favor.~Pedido|It's on its way.=Está a caminho.~Entrega|Enjoy your meal!=Bom apetite!~Entregador",
 tf="Delivery é entrega em casa.=T|Pablo paga em dinheiro.=F|It will take thirty minutes.=T|A pizza é de calabresa.=F",
 odd="pizza,pasta,burger,address=address|cash,card,tip,hungry=hungry"),
dict(n=53, gr='imper', vb='open,click,search,download,connect',
 c1="Palavras da internet|Em inglês, 'to google' virou verbo (pesquisar). 'Website' é o site, 'link' é o link e 'password' é a senha. 'Log in' é entrar e 'log out' é sair da conta.",
 c2="Segurança online|Use senhas longas e diferentes em cada site. Em inglês, 'two-factor authentication' é a verificação em duas etapas. 'Never share your password' é uma regra básica.",
 ar=("A lesson on the screen","At the library, Max helps older neighbors with the internet. Today he teaches Jin how to use an app. \"First, open the app,\" says Max. \"Then click the search icon. Next, type your name.\" Jin takes notes in a small notebook. \"What if I forget my password?\" he asks. \"Click 'Forgot password' and follow the steps,\" says Max. After an hour, Jin can send an email by himself. He shows Max a photo of his granddaughter and smiles. \"Technology is not so hard,\" he says.","Max ensina Jin a usar aplicativos e a internet.","Onde Max ensina?=At the library|At school|At home;;O que Jin mostra?=A photo|A song|A game"),
 ex="Do a quick search.=Faça uma busca rápida.~Internet|It's loading.=Está carregando.~Esperar|Log in / Log out=Entrar / sair~Conta|I'm offline.=Estou offline.~Sem internet|Go viral=Viralizar~Redes",
 tf="Click é clicar.=T|Password é senha.=T|Max é o aluno.=F|Jin esquece a senha.=T",
 odd="app,website,link,sandwich=sandwich|open,click,search,happy=happy"),
dict(n=54, gr='freq', vb='exercise,walk,drink,eat,go',
 c1="Always, usually, sometimes, never|Pense em uma escala: always (100%), usually (80%), often (60%), sometimes (40%), rarely (10%), never (0%). Eles vão antes do verbo principal e depois de be.",
 c2="Hábitos saudáveis|Segundo a OMS, adultos devem fazer 150 minutos de exercício por semana. Em inglês: 'Get at least 30 minutes of exercise a day'. Pequenos hábitos, como caminhar 10 minutos, já ajudam.",
 ar=("Healthy habits","Kofi exercises three times a week. He always drinks a lot of water, usually eats fruit for breakfast and sometimes eats chocolate. He never skips breakfast. Mei is different: she rarely exercises, but she walks to work every day. She often drinks tea and seldom eats fast food. They both agree that small habits matter more than big plans. \"Do a little every day,\" says Kofi. \"Yes,\" says Mei, \"and never give up!\" They shake hands and promise to walk together on Sundays.","Kofi e Mei têm hábitos diferentes, mas concordam que os pequenos contam.","O que Kofi sempre faz?=Drinks water|Eats chocolate|Skips breakfast;;Como Mei vai ao trabalho?=Walks|By bus|By car"),
 ex="Once in a blue moon=De vez em nunca~Raramente|Every now and then=De vez em quando~Frequência|As a rule=Em geral~Hábito|Nine times out of ten=Quase sempre~Frequência|Never in a million years!=Nunca na vida!~Exagero",
 tf="Always é sempre.=T|Never é frequentemente.=F|O advérbio vem antes do verbo principal.=T|Kofi se exercita três vezes por semana.=T",
 odd="always,usually,sometimes,table=table|exercise,walk,run,chocolate=chocolate"),
dict(n=55, gr='doq', vb='get,have,work,train,sleep',
 c1="Entrevistas|Em inglês, 'interview' pode ser uma conversa de emprego ou uma entrevista de jornal. Para entrevistar bem, faça perguntas abertas: 'What time do you get up?' e 'How do you relax?'.",
 c2="Treinadores famosos|Os melhores treinadores de basquete e futebol seguem rotinas rígidas: acordam cedo, treinam cedo e dormem cedo. 'Discipline' é a palavra-chave: disciplina em inglês.",
 ar=("A coach's day","Joe is a basketball coach. He gets up at five thirty, has eggs and fruit for breakfast and runs five kilometers. At nine he goes to the school gym and prepares the practice. After lunch, he trains the kids until eight. At night he reads a book and goes to bed at ten. \"Do you ever get tired?\" asks Naomi, the journalist. \"Of course,\" says Joe, \"but I love my routine. It keeps me happy and healthy.\" Naomi writes it down for her blog.","A rotina do treinador Joe, da corrida ao livro da noite.","Quantos quilômetros Joe corre?=Five|Ten|Two;;O que ele faz à noite?=Reads a book|Watches TV|Plays soccer"),
 ex="What's your day like?=Como é o seu dia?~Rotina|I'm a creature of habit.=Sou pessoa de hábitos.~Rotina|I stick to my routine.=Sigo minha rotina.~Rotina|I wind down by reading.=Relaxo lendo.~Relaxar|Day in, day out=Todo santo dia~Rotina",
 tf="Does he work? é uma pergunta correta.=T|Does she works? está correto.=F|Joe treina crianças.=T|Joe acorda às oito.=F",
 odd="coach,gym,team,spoon=spoon|do,does,did,table=table"),
dict(n=56, gr='comp', vb='compare,choose,walk,climb,prefer',
 c1="Mais ou menos?|Compare com -er (taller) ou more (more difficult). 'As ... as' diz que são iguais: 'She is as tall as me'. Para dizer que é diferente: 'not as ... as'.",
 c2="Trilhas famosas|O 'Appalachian Trail', nos EUA, tem 3.500 km. No Reino Unido, o 'Coast to Coast' atravessa a Inglaterra de mar a mar. Em inglês, 'hiking' é fazer trilha e 'trekking' é caminhada longa.",
 ar=("Two trails","There are two trails near Maple Street. The blue trail is long and beautiful, but it is more difficult. It has a lake, tall trees and a great view. The red trail is shorter and easier, and it has a small waterfall. Ian takes the blue one on Saturdays when he has a lot of energy. On Sundays he takes the red one because he is tired. Una prefers the red one. \"It's cheaper, easier and safer,\" she says. \"But the blue one is more beautiful,\" says Ian. They both smile.","Duas trilhas: uma mais bela e difícil, outra mais fácil.","O que a trilha azul tem?=A lake|A waterfall|A cafe;;Quando Ian usa a vermelha?=On Sundays|On Saturdays|Never"),
 ex="It's a different ball game.=É outra história.~Comparação|Apples and oranges=Coisas incomparáveis~Idiom|The more, the merrier.=Quanto mais, melhor.~Festa|Easier said than done.=Mais fácil falar que fazer.~Provérbio|Better late than never.=Antes tarde do que nunca.~Provérbio",
 tf="Taller é mais alto.=T|More beautiful é mais bonito.=T|A trilha vermelha é mais longa.=F|Una prefere a trilha vermelha.=T",
 odd="taller,bigger,faster,mountain=mountain|good,better,best,table=table"),
dict(n=57, gr='super', vb='climb,visit,see,choose,know',
 c1="O maior, o menor|Superlativos têm 'the': the tallest, the most beautiful. O Everest é 'the highest mountain in the world'. O rio Amazonas é 'the longest river' em volume. Quase todo ranking usa essa forma.",
 c2="Recordes do mundo|O Guinness World Records registra os maiores e mais curiosos recordes do mundo. Em inglês: 'the biggest pizza', 'the longest hair', 'the fastest runner'. Um recorde é 'a record' e quebrar é 'to break a record'.",
 ar=("The mountain book","Nora has a big book about mountains. The highest mountain is in Asia: Mount Everest. The most popular mountain is in the Alps. The oldest mountain range is in Africa. The coldest one is in Antarctica. The most beautiful one, in Nora's opinion, is the small mountain near her grandmother's village. It has snow all year and the best sunsets in the world. \"One day,\" she says, \"I'll climb the highest mountain.\" Sven says, \"Maybe we can go together.\" Nora smiles.","O livro de montanhas de Nora lista picos famosos.","Onde está a mais popular?=In the Alps|In Asia|In Africa;;Qual a favorita de Nora?=Near her grandmother's village|The highest|The oldest"),
 ex="It's the best of the best.=É o melhor dos melhores.~Elogio|It's the most beautiful place ever.=É o lugar mais lindo.~Elogio|Last but not least=Por último, mas não menos importante~Lista|The sky's the limit.=O céu é o limite.~Possibilidades|At its best=No seu melhor~Descrever",
 tf="Highest é o mais alto.=T|The most popular é o mais popular.=T|A montanha mais fria está na Ásia.=F|Everest é a montanha mais alta.=T",
 odd="highest,biggest,oldest,mountain=mountain|best,worst,most,table=table"),
dict(n=58, gr='imper', vb='mix,cut,add,pour,cook',
 c1="Receitas em inglês|Receitas usam o imperativo: 'Mix the eggs'. Palavras-chave: 'ingredients' (ingredientes), 'serves 4' (serve 4 pessoas), 'preheat the oven' (pré-aqueça o forno).",
 c2="Panquecas americanas|As 'pancakes' americanas são grossas, com 'maple syrup' (xarope de bordo), manteiga e frutas. No Reino Unido são finas, como crepes, e comem-se no 'Pancake Day', na terça-feira antes da Quaresma.",
 ar=("Sunday pancakes","On Sunday, Lucia and Gus make pancakes. First they mix two eggs, one cup of flour and some milk in a big bowl. Then Lucia heats the pan. Next she pours some of the mix into the pan. After two minutes she turns the pancake over. Finally she puts honey and fruit on top. Gus tries one and says, \"It's delicious!\" Lucia laughs. \"Don't eat them all! We have a big family!\" They put the pancakes on a big plate and call everyone for breakfast.","Lucia e Gus fazem panquecas seguindo uma receita simples.","O que colocam por cima?=Honey and fruit|Chocolate|Cheese;;Quando as fazem?=On Sunday|On Monday|On Friday"),
 ex="Piece of cake!=Moleza!~Algo fácil|Cooking up a storm=Cozinhando com vontade~Cozinhar muito|Too many cooks spoil the broth.=Muitos cozinheiros estragam o caldo.~Provérbio|Bon appétit!=Bom apetite!~Antes de comer|It's finger-licking good.=É de lamber os dedos.~Comida boa",
 tf="First, mix é um imperativo.=T|Don't burn it! significa Não queime!=T|As panquecas são servidas com mel e fruta.=T|Gus não gosta das panquecas.=F",
 odd="mix,pour,stir,table=table|eggs,flour,milk,pan=pan"),
dict(n=59, gr='must', vb='stop,wait,park,wear,drive',
 c1="Placas que você precisa conhecer|STOP é parar. YIELD (EUA) ou GIVE WAY (UK) é dê a preferência. NO PARKING é proibido estacionar. EXIT é saída e ENTRANCE é entrada.",
 c2="Dirigir pela esquerda|No Reino Unido, na Irlanda, na Austrália e no Japão dirige-se pela esquerda. Nos EUA e no Brasil, pela direita. Muito cuidado ao alugar carro no exterior e olhar para o lado certo ao atravessar!",
 ar=("Signs everywhere","Maple Street has many signs. A red sign says STOP. A blue sign says PARKING. A yellow sign says CHILDREN CROSSING. In the park, a sign says KEEP OFF THE GRASS. At the school, a sign says SPEED LIMIT 20. Greta reads every sign carefully on her way. She is a new driver, and she knows that signs keep everybody safe. \"You must always stop at a red light,\" says Pete. \"And you mustn't use your phone while you drive.\" Greta nods. \"Safety first!\"","As placas dão regras e avisos; Greta as lê com atenção.","O que diz a placa vermelha?=STOP|PARKING|EXIT;;Quem lê as placas?=Greta|Pete|Mia"),
 ex="Keep off the grass.=Não pise na grama.~Placa|Safety first!=Segurança em primeiro lugar!~Aviso|Mind the step.=Cuidado com o degrau.~Aviso|No entry=Entrada proibida~Placa|Beware of the dog.=Cuidado com o cão.~Placa",
 tf="Must expressa obrigação.=T|Mustn't significa proibido.=T|Os sinais vermelhos mandam andar.=F|Greta é uma nova motorista.=T",
 odd="stop,exit,parking,sandwich=sandwich|must,mustn't,can't,red=red"),
dict(n=60, gr='comp', vb='buy,sell,cook,teach,order',
 c1="Feiras de rua|Em inglês, 'flea market' é um mercado de pulgas, onde se vendem objetos usados. 'Farmers' market' vende frutas e verduras frescas. 'Garage sale' é a venda de objetos usados na garagem da casa.",
 c2="Regras do mercado|Em muitos mercados é comum negociar: 'Can you do it for ten dollars?'. Em lojas normais não se negocia. Saber a diferença é parte da cultura de compras em países de língua inglesa.",
 ar=("The Offers Fair","The Offers Fair is a monthly market on Maple Street. People sell books, tools and homemade food. Lucia teaches a pancake class and Gus buys glue and a book. A little girl sells lemonade for one dollar. It is cheaper than at the café and tastes better. Mia explains the rules of the fair: no parking in the middle of the street, always say thank you and take your trash home. At the end of the day, everybody is tired but happy. \"See you next month!\" shouts Mia.","A feira mensal reúne compras, aulas e regras simples.","O que Lucia ensina?=Pancakes|Music|Swimming;;Quanto custa a limonada?=One dollar|Five dollars|Ten dollars"),
 ex="What a bargain!=Que pechincha!~Compra boa|It's a steal!=É uma barbada!~Preço baixo|You get what you pay for.=Você leva o que paga.~Provérbio|It's worth every penny.=Vale cada centavo.~Valor|Out of stock=Em falta~Loja",
 tf="Flea market vende objetos usados.=T|A limonada custa dez dólares.=F|Mia explica as regras.=T|A feira é diária.=F",
 odd="books,tools,food,fridge=fridge|buy,sell,pay,sleep=sleep"),
]
